package com.bananalab.lite;
import android.content.*;import java.util.*;import org.json.*;
/** Compile uncommitted sources; commit only if the project and revision still match. */
final class GeneralSourceChat{
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-general-source",0);}
 static boolean sourceMessage(String s){return s.length()<=16000&&s.contains("```")&&s.matches("(?isu)^(?:banana[, ]+)?(?:(?:podes|podrias|quiero que|necesito que) )?(?:cambia|cambiame|reescribe|reemplaza|crea|agrega) .*\\.java.*");}
 static void recover(Context c)throws Exception{String raw=prefs(c).getString("pending","");if(raw.isEmpty())return;JSONObject r=new JSONObject(raw);String w=JavaProject.prefs(c).getString("working","{}");if(!r.getString("base").equals(JavaProject.fingerprint(c)))throw new IllegalStateException("Punto de recuperación de una base anterior conservado");if(w.equals(r.getJSONObject("after").toString())){if(!prefs(c).edit().putString("transaction",raw).remove("pending").commit())throw new IllegalStateException("Registro pendiente");}else if(w.equals(r.getJSONObject("before").toString()))prefs(c).edit().remove("pending").commit();else throw new IllegalStateException("La copia cambió con un lote pendiente; conservé ambas evidencias");}
 static String apply(Context c,GeneralEditPlan plan)throws Exception{NaturalCoding.project(c);recover(c);String base=JavaProject.fingerprint(c);int revision=JavaProject.prefs(c).getInt("revision",0);JSONObject before=JavaProject.working(c),candidate=new JSONObject(before.toString());Map<String,String> changed=plan.apply(JavaProject.files(c,before));for(Map.Entry<String,String> e:changed.entrySet())candidate.put(e.getKey(),e.getValue());if(candidate.toString().length()>1000000)throw new IllegalArgumentException("La copia supera1MB");String report=JavaProject.compile(c,candidate,false);if(!report.startsWith("Compilación completa aprobada"))return "Rechacé el lote: el proyecto no compila. Conservé la copia anterior.\n"+report;
 synchronized(JavaProject.class){if(revision!=JavaProject.prefs(c).getInt("revision",0)||!base.equals(JavaProject.fingerprint(c))||!before.toString().equals(JavaProject.prefs(c).getString("working","{}")))throw new IllegalStateException("La copia cambió durante la comprobación; no incorporé el lote");JSONObject row=new JSONObject().put("base",base).put("before",before).put("after",candidate).put("files",new JSONArray(changed.keySet()));if(!prefs(c).edit().putString("pending",row.toString()).commit())throw new IllegalStateException("No pude guardar la recuperación");JavaProject.stageBatch(c,changed);if(!prefs(c).edit().putString("transaction",row.toString()).remove("pending").commit())throw new IllegalStateException("Copia preparada con registro pendiente de recuperación");}
 String text="Preparé cambios generales en "+changed.size()+" archivos Java:\n"+JavaCompat.join(", ",changed.keySet())+"\nEl proyecto completo compila. No ejecuté ese código ni comprobé su comportamiento. Podés pedirme actualizar la app para incorporarlo a la APK normal, o deshacer la edición de código antes de incorporarla.";prefs(c).edit().putString("receipt",text).commit();return text;}
 static String undo(Context c)throws Exception{synchronized(JavaProject.class){recover(c);JSONObject r=new JSONObject(prefs(c).getString("transaction","{}"));if(!r.has("before"))return "No hay edición general registrada";if(!r.getString("base").equals(JavaProject.fingerprint(c))||!r.getJSONObject("after").toString().equals(JavaProject.prefs(c).getString("working","{}")))throw new IllegalStateException("La copia cambió después de esta edición; no la sobrescribí");if(!JavaProject.prefs(c).edit().putString("working",r.getJSONObject("before").toString()).putInt("revision",JavaProject.prefs(c).getInt("revision",0)+1).remove("compiledHash").commit())throw new IllegalStateException("No pude recuperar las fuentes");prefs(c).edit().remove("transaction").commit();return "Recuperé la copia anterior; la app instalada se conserva.";}}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=NaturalCoding.normalize(input);boolean undo=q.matches("deshace la edicion de codigo|deshace esa edicion de codigo");if(q.equals("mostrame la edicion de codigo"))return MobileCore.say(c,prefs(c).getString("receipt","Sin edición registrada"),"app_ajuste");GeneralEditPlan p;try{p=undo?null:GeneralEditPlan.parse(input);}catch(Exception e){return MobileCore.say(c,"No preparé la edición: "+AndroidRepair.summary(e),"app_ajuste");}if(!undo&&p==null)return null;JavaChat.owner=Thread.currentThread();try{return MobileCore.say(c,undo?undo(c):apply(c,p),"app_ajuste");}catch(Exception e){return MobileCore.say(c,"No completé la edición general: "+AndroidRepair.summary(e),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
